/* ============================================================
   EXPENSE & BUDGET VISUALIZER — style.css
   Mobile-first, responsive, supports light/dark themes
   ============================================================ */

/* ── 1. CSS Custom Properties (Design Tokens) ── */
:root {
  /* Light theme */
  --color-bg:           #f0f2f5;
  --color-surface:      #ffffff;
  --color-surface-alt:  #f8f9fb;
  --color-border:       #e2e6ea;
  --color-text:         #1a1d23;
  --color-text-muted:   #6b7280;
  --color-primary:      #4f46e5;
  --color-primary-hover:#4338ca;
  --color-primary-light:#ede9fe;
  --color-danger:       #ef4444;
  --color-danger-light: #fee2e2;
  --color-warning:      #f59e0b;
  --color-warning-light:#fef3c7;
  --color-success:      #10b981;
  --color-success-light:#d1fae5;

  /* Category colours */
  --color-food:      #f97316;
  --color-transport: #3b82f6;
  --color-fun:       #a855f7;

  /* Spacing & shape */
  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  18px;
  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md:  0 4px 16px rgba(0,0,0,.10);
  --transition: 0.22s ease;
}

[data-theme="dark"] {
  --color-bg:           #0f1117;
  --color-surface:      #1a1d27;
  --color-surface-alt:  #21253a;
  --color-border:       #2d3248;
  --color-text:         #e8eaf0;
  --color-text-muted:   #8b92a8;
  --color-primary:      #6d63ff;
  --color-primary-hover:#7c73ff;
  --color-primary-light:#2d2b5a;
  --color-danger:       #f87171;
  --color-danger-light: #3b1f1f;
  --color-warning:      #fbbf24;
  --color-warning-light:#3b2f0f;
  --color-success:      #34d399;
  --color-success-light:#0d2e22;

  --color-food:      #fb923c;
  --color-transport: #60a5fa;
  --color-fun:       #c084fc;

  --shadow-sm:  0 1px 3px rgba(0,0,0,.4);
  --shadow-md:  0 4px 16px rgba(0,0,0,.5);
}

/* ── 2. Reset & Base ── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  transition: background-color var(--transition), color var(--transition);
}

h1, h2, h3 {
  line-height: 1.25;
}

/* ── 3. Header ── */
.app-header {
  background-color: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 100;
  transition: background-color var(--transition), border-color var(--transition);
}

.header-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0.85rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.brand-icon {
  font-size: 1.6rem;
  line-height: 1;
}

.brand-title {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -0.3px;
}

/* Theme toggle button */
.theme-toggle {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.45rem 0.9rem;
  border-radius: 999px;
  border: 1.5px solid var(--color-border);
  background: var(--color-surface-alt);
  color: var(--color-text);
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition),
              box-shadow var(--transition);
  white-space: nowrap;
}

.theme-toggle:hover {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.theme-icon {
  font-size: 1rem;
}

/* ── 4. Main container ── */
.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 2.5rem;
}

/* ── 5. Balance Section ── */
.balance-section {
  margin-bottom: 1.25rem;
}

.balance-card {
  background: linear-gradient(135deg, var(--color-primary) 0%, #7c3aed 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 1.6rem 1.75rem;
  box-shadow: var(--shadow-md);
  transition: box-shadow var(--transition);
}

.balance-label {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-bottom: 0.3rem;
}

.balance-amount {
  font-size: 2.6rem;
  font-weight: 800;
  letter-spacing: -1px;
  margin-bottom: 0.8rem;
}

.budget-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.4rem;
  font-size: 0.82rem;
  opacity: 0.9;
  margin-bottom: 0.55rem;
}

.budget-status {
  font-weight: 700;
  padding: 0.2rem 0.65rem;
  border-radius: 999px;
  background: rgba(255,255,255,0.2);
}

.budget-status.over  { background: rgba(239,68,68,0.8); }
.budget-status.near  { background: rgba(245,158,11,0.8); }
.budget-status.good  { background: rgba(16,185,129,0.8); }

/* Progress bar */
.budget-bar-track {
  background: rgba(255,255,255,0.25);
  border-radius: 999px;
  height: 8px;
  overflow: hidden;
}

.budget-bar-fill {
  height: 100%;
  border-radius: 999px;
  background: #fff;
  width: 0%;
  transition: width 0.5s ease, background 0.3s ease;
}

.budget-bar-fill.near { background: #fbbf24; }
.budget-bar-fill.over { background: #f87171; }

/* ── 6. Budget Warning Banner ── */
.budget-warning {
  background: var(--color-warning-light);
  border: 1.5px solid var(--color-warning);
  color: var(--color-text);
  border-radius: var(--radius-md);
  padding: 0.8rem 1.1rem;
  margin-bottom: 1.25rem;
  font-size: 0.9rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  animation: slideDown 0.3s ease;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── 7. Grid Layout ── */
.main-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
}

@media (min-width: 768px) {
  .main-grid {
    grid-template-columns: 1fr 1fr;
    align-items: start;
  }
}

@media (min-width: 1024px) {
  .main-grid {
    grid-template-columns: 5fr 4fr;
  }
}

/* ── 8. Cards ── */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.35rem 1.4rem;
  box-shadow: var(--shadow-sm);
  transition: background-color var(--transition), border-color var(--transition);
}

.card-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: 1.1rem;
  padding-bottom: 0.65rem;
  border-bottom: 1.5px solid var(--color-border);
}

/* stack left-col cards */
.left-col {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.right-col {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── 9. Form ── */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 1rem;
}

.form-group label {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.form-group input,
.form-group select {
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius-sm);
  border: 1.5px solid var(--color-border);
  background: var(--color-surface-alt);
  color: var(--color-text);
  font-size: 0.95rem;
  font-family: inherit;
  transition: border-color var(--transition), box-shadow var(--transition),
              background var(--transition);
  outline: none;
  width: 100%;
}

.form-group input:focus,
.form-group select:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px var(--color-primary-light);
  background: var(--color-surface);
}

.form-group input.error,
.form-group select.error {
  border-color: var(--color-danger);
  box-shadow: 0 0 0 3px var(--color-danger-light);
}

.form-group input::placeholder {
  color: var(--color-text-muted);
  opacity: 0.7;
}

/* Remove number input spinners */
input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  -webkit-appearance: none;
}
input[type="number"] { -moz-appearance: textfield; }

.field-error {
  font-size: 0.78rem;
  color: var(--color-danger);
  min-height: 1rem;
  font-weight: 500;
}

/* ── 10. Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.7rem 1.2rem;
  border-radius: var(--radius-sm);
  border: none;
  font-size: 0.95rem;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), transform 0.1s ease,
              box-shadow var(--transition);
  width: 100%;
}

.btn:active { transform: scale(0.97); }

.btn-primary {
  background: var(--color-primary);
  color: #fff;
  box-shadow: 0 2px 8px rgba(79,70,229,0.3);
}

.btn-primary:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 12px rgba(79,70,229,0.4);
}

.btn-delete {
  background: transparent;
  color: var(--color-danger);
  border: 1.5px solid var(--color-danger);
  padding: 0.3rem 0.65rem;
  border-radius: var(--radius-sm);
  font-size: 0.78rem;
  width: auto;
  font-weight: 600;
  transition: background var(--transition), color var(--transition);
  cursor: pointer;
  white-space: nowrap;
}

.btn-delete:hover {
  background: var(--color-danger);
  color: #fff;
}

/* ── 11. Sort Controls ── */
.list-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-bottom: 1.1rem;
  padding-bottom: 0.65rem;
  border-bottom: 1.5px solid var(--color-border);
}

.list-header .card-title {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
}

.sort-controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.sort-controls label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--color-text-muted);
  white-space: nowrap;
}

.sort-controls select {
  padding: 0.3rem 0.6rem;
  border-radius: var(--radius-sm);
  border: 1.5px solid var(--color-border);
  background: var(--color-surface-alt);
  color: var(--color-text);
  font-size: 0.8rem;
  font-family: inherit;
  cursor: pointer;
  outline: none;
  transition: border-color var(--transition), background var(--transition);
}

.sort-controls select:focus {
  border-color: var(--color-primary);
}

/* ── 12. Transaction List ── */
.transaction-list {
  max-height: 420px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding-right: 2px; /* space for scrollbar */
}

/* Custom scrollbar */
.transaction-list::-webkit-scrollbar { width: 5px; }
.transaction-list::-webkit-scrollbar-track { background: transparent; }
.transaction-list::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 999px;
}

/* Empty State */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2.5rem 1rem;
  color: var(--color-text-muted);
  text-align: center;
  gap: 0.6rem;
}

.empty-icon { font-size: 2.5rem; }

.empty-state p {
  font-size: 0.9rem;
  line-height: 1.7;
}

/* Transaction Item */
.transaction-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.7rem 0.9rem;
  border-radius: var(--radius-md);
  background: var(--color-surface-alt);
  border: 1px solid var(--color-border);
  transition: border-color var(--transition), box-shadow var(--transition),
              background var(--transition);
  animation: fadeIn 0.25s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

.transaction-item:hover {
  border-color: var(--color-primary);
  box-shadow: 0 2px 8px rgba(79,70,229,0.1);
}

/* Category dot/icon */
.tx-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.tx-icon.food      { background: rgba(249,115,22,0.15);  }
.tx-icon.transport { background: rgba(59,130,246,0.15);  }
.tx-icon.fun       { background: rgba(168,85,247,0.15);  }

/* Transaction info */
.tx-info {
  flex: 1;
  min-width: 0;
}

.tx-name {
  font-size: 0.9rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--color-text);
}

.tx-meta {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  margin-top: 1px;
}

.tx-badge {
  display: inline-block;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-right: 4px;
}

.tx-badge.food      { background: rgba(249,115,22,0.15);  color: var(--color-food); }
.tx-badge.transport { background: rgba(59,130,246,0.15);  color: var(--color-transport); }
.tx-badge.fun       { background: rgba(168,85,247,0.15);  color: var(--color-fun); }

.tx-amount {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  white-space: nowrap;
  flex-shrink: 0;
}

/* ── 13. Chart ── */
.chart-card {
  display: flex;
  flex-direction: column;
}

.chart-wrapper {
  position: relative;
  width: 100%;
  max-width: 260px;
  margin: 0 auto 1rem;
  aspect-ratio: 1;
}

.chart-wrapper canvas {
  width: 100% !important;
  height: 100% !important;
}

.chart-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1.5rem 1rem;
  color: var(--color-text-muted);
  text-align: center;
  font-size: 0.88rem;
}

.chart-empty span { font-size: 2rem; }

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem 1rem;
  margin-top: 0.25rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.8rem;
  font-weight: 600;
}

.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── 14. Category Summary ── */
.summary-list {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.summary-empty {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  text-align: center;
  padding: 0.75rem 0;
}

.summary-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.summary-item-left {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.88rem;
  font-weight: 600;
}

.summary-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.summary-right {
  font-size: 0.88rem;
  font-weight: 700;
}

.summary-bar-track {
  flex: 1;
  background: var(--color-border);
  border-radius: 999px;
  height: 6px;
  overflow: hidden;
  min-width: 40px;
}

.summary-bar-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.5s ease;
}

/* ── 15. Footer ── */
.app-footer {
  text-align: center;
  padding: 1.5rem 1rem;
  font-size: 0.78rem;
  color: var(--color-text-muted);
  border-top: 1px solid var(--color-border);
  margin-top: 1.5rem;
  transition: border-color var(--transition);
}

/* ── 16. Utility ── */
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

/* ── 17. Responsive tweaks ── */
@media (max-width: 480px) {
  .balance-amount { font-size: 2rem; }
  .balance-card   { padding: 1.2rem 1.1rem; }
  .container      { padding: 1rem 0.9rem 2rem; }
  .card           { padding: 1rem 1.05rem; }

  .sort-controls { width: 100%; }
  .sort-controls select { flex: 1; }
  .list-header    { flex-direction: column; align-items: flex-start; }
}

/* ============================================================
   EXPENSE & BUDGET VISUALIZER — script.js
   Vanilla JS | LocalStorage | Chart.js 4.x
   ============================================================ */

'use strict';

/* ── Constants ── */
const BUDGET_LIMIT   = 100;
const STORAGE_KEY    = 'budgetviz_transactions';
const THEME_KEY      = 'budgetviz_theme';

const CATEGORY_META = {
  Food:      { icon: '🍔', color: '#f97316', darkColor: '#fb923c', cssClass: 'food' },
  Transport: { icon: '🚌', color: '#3b82f6', darkColor: '#60a5fa', cssClass: 'transport' },
  Fun:       { icon: '🎉', color: '#a855f7', darkColor: '#c084fc', cssClass: 'fun' },
};

/* ── State ── */
let transactions = [];   // Array of { id, name, amount, category, date }
let pieChart     = null; // Chart.js instance

/* ── DOM References ── */
const $ = id => document.getElementById(id);

const dom = {
  html:           document.documentElement,
  themeToggle:    $('themeToggle'),
  themeIcon:      $('themeIcon'),
  themeLabel:     $('themeLabel'),
  totalBalance:   $('totalBalance'),
  balanceCard:    $('balanceCard'),
  budgetBarFill:  $('budgetBarFill'),
  budgetStatus:   $('budgetStatus'),
  budgetWarning:  $('budgetWarning'),
  form:           $('transactionForm'),
  itemName:       $('itemName'),
  amount:         $('amount'),
  category:       $('category'),
  itemNameError:  $('itemNameError'),
  amountError:    $('amountError'),
  categoryError:  $('categoryError'),
  txList:         $('transactionList'),
  emptyState:     $('emptyState'),
  sortSelect:     $('sortSelect'),
  pieCanvas:      $('pieChart'),
  chartWrapper:   $('chartWrapper'),
  chartEmpty:     $('chartEmpty'),
  chartLegend:    $('chartLegend'),
  summaryList:    $('summaryList'),
};

/* ═══════════════════════════════════════════
   1. THEME MANAGEMENT
═══════════════════════════════════════════ */

function initTheme() {
  const saved = localStorage.getItem(THEME_KEY) || 'light';
  applyTheme(saved);
}

function applyTheme(theme) {
  dom.html.setAttribute('data-theme', theme);
  localStorage.setItem(THEME_KEY, theme);

  if (theme === 'dark') {
    dom.themeIcon.textContent  = '☀️';
    dom.themeLabel.textContent = 'Light Mode';
  } else {
    dom.themeIcon.textContent  = '🌙';
    dom.themeLabel.textContent = 'Dark Mode';
  }

  // Re-render chart so colours match theme
  if (pieChart) updateChart();
}

function toggleTheme() {
  const current = dom.html.getAttribute('data-theme');
  applyTheme(current === 'dark' ? 'light' : 'dark');
}

/* ═══════════════════════════════════════════
   2. LOCAL STORAGE
═══════════════════════════════════════════ */

function loadTransactions() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    transactions = raw ? JSON.parse(raw) : [];
  } catch {
    transactions = [];
  }
}

function saveTransactions() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(transactions));
}

/* ═══════════════════════════════════════════
   3. FORM VALIDATION & SUBMISSION
═══════════════════════════════════════════ */

function clearErrors() {
  dom.itemNameError.textContent  = '';
  dom.amountError.textContent    = '';
  dom.categoryError.textContent  = '';
  dom.itemName.classList.remove('error');
  dom.amount.classList.remove('error');
  dom.category.classList.remove('error');
}

function validateForm() {
  clearErrors();
  let valid = true;

  const name   = dom.itemName.value.trim();
  const amt    = parseFloat(dom.amount.value);
  const cat    = dom.category.value;

  if (!name) {
    dom.itemNameError.textContent = 'Item name is required.';
    dom.itemName.classList.add('error');
    valid = false;
  } else if (name.length > 60) {
    dom.itemNameError.textContent = 'Name must be 60 characters or fewer.';
    dom.itemName.classList.add('error');
    valid = false;
  }

  if (!dom.amount.value.trim()) {
    dom.amountError.textContent = 'Amount is required.';
    dom.amount.classList.add('error');
    valid = false;
  } else if (isNaN(amt) || amt <= 0) {
    dom.amountError.textContent = 'Enter a valid amount greater than 0.';
    dom.amount.classList.add('error');
    valid = false;
  } else if (amt > 1_000_000) {
    dom.amountError.textContent = 'Amount is too large.';
    dom.amount.classList.add('error');
    valid = false;
  }

  if (!cat) {
    dom.categoryError.textContent = 'Please select a category.';
    dom.category.classList.add('error');
    valid = false;
  }

  return valid;
}

function handleFormSubmit(e) {
  e.preventDefault();
  if (!validateForm()) return;

  const transaction = {
    id:       crypto.randomUUID(),
    name:     dom.itemName.value.trim(),
    amount:   parseFloat(parseFloat(dom.amount.value).toFixed(2)),
    category: dom.category.value,
    date:     new Date().toISOString(),
  };

  transactions.unshift(transaction);
  saveTransactions();
  render();

  // Reset form
  dom.form.reset();
  clearErrors();
  dom.itemName.focus();
}

/* ═══════════════════════════════════════════
   4. DELETE TRANSACTION
═══════════════════════════════════════════ */

function deleteTransaction(id) {
  transactions = transactions.filter(t => t.id !== id);
  saveTransactions();
  render();
}

/* ═══════════════════════════════════════════
   5. SORTING
═══════════════════════════════════════════ */

function getSortedTransactions() {
  const mode = dom.sortSelect.value;
  const copy = [...transactions];

  switch (mode) {
    case 'date-asc':
      return copy.sort((a, b) => new Date(a.date) - new Date(b.date));
    case 'date-desc':
      return copy.sort((a, b) => new Date(b.date) - new Date(a.date));
    case 'amount-desc':
      return copy.sort((a, b) => b.amount - a.amount);
    case 'amount-asc':
      return copy.sort((a, b) => a.amount - b.amount);
    case 'category':
      return copy.sort((a, b) => a.category.localeCompare(b.category));
    default:
      return copy;
  }
}

/* ═══════════════════════════════════════════
   6. TOTAL & BUDGET BAR
═══════════════════════════════════════════ */

function updateBalanceUI() {
  const total      = transactions.reduce((s, t) => s + t.amount, 0);
  const pct        = Math.min((total / BUDGET_LIMIT) * 100, 100);
  const isOver     = total > BUDGET_LIMIT;
  const isNear     = !isOver && total >= BUDGET_LIMIT * 0.8;

  // Amount display
  dom.totalBalance.textContent = formatCurrency(total);

  // Progress bar
  dom.budgetBarFill.style.width = pct + '%';
  dom.budgetBarFill.classList.toggle('over',  isOver);
  dom.budgetBarFill.classList.toggle('near',  isNear && !isOver);

  // Status badge
  if (isOver) {
    dom.budgetStatus.textContent = '🔴 Over Budget';
    dom.budgetStatus.className   = 'budget-status over';
  } else if (isNear) {
    dom.budgetStatus.textContent = '🟡 Near Limit';
    dom.budgetStatus.className   = 'budget-status near';
  } else {
    dom.budgetStatus.textContent = total > 0 ? '🟢 On Track' : '';
    dom.budgetStatus.className   = 'budget-status good';
  }

  // Warning banner
  dom.budgetWarning.style.display = isOver ? 'flex' : 'none';
}

/* ═══════════════════════════════════════════
   7. TRANSACTION LIST RENDERING
═══════════════════════════════════════════ */

function renderTransactionList() {
  const sorted = getSortedTransactions();

  // Clear all children except empty-state template
  dom.txList.innerHTML = '';

  if (sorted.length === 0) {
    dom.txList.appendChild(createEmptyState());
    return;
  }

  const frag = document.createDocumentFragment();
  sorted.forEach(t => frag.appendChild(createTransactionEl(t)));
  dom.txList.appendChild(frag);
}

function createEmptyState() {
  const div = document.createElement('div');
  div.className = 'empty-state';
  div.id = 'emptyState';
  div.innerHTML = `
    <span class="empty-icon">📋</span>
    <p>No transactions yet.<br/>Add one above to get started!</p>
  `;
  return div;
}

function createTransactionEl(t) {
  const meta     = CATEGORY_META[t.category] || CATEGORY_META.Fun;
  const cssClass = meta.cssClass;
  const dateStr  = formatDate(t.date);

  const item = document.createElement('div');
  item.className = 'transaction-item';
  item.dataset.id = t.id;

  item.innerHTML = `
    <div class="tx-icon ${cssClass}" aria-hidden="true">${meta.icon}</div>
    <div class="tx-info">
      <div class="tx-name" title="${escapeHtml(t.name)}">${escapeHtml(t.name)}</div>
      <div class="tx-meta">
        <span class="tx-badge ${cssClass}">${t.category}</span>
        <span>${dateStr}</span>
      </div>
    </div>
    <span class="tx-amount">${formatCurrency(t.amount)}</span>
    <button class="btn btn-delete" data-id="${t.id}" aria-label="Delete ${escapeHtml(t.name)}">
      Delete
    </button>
  `;
  return item;
}

/* ═══════════════════════════════════════════
   8. PIE CHART (Chart.js)
═══════════════════════════════════════════ */

function getCategoryTotals() {
  const totals = {};
  transactions.forEach(t => {
    totals[t.category] = (totals[t.category] || 0) + t.amount;
  });
  return totals;
}

function getChartColors(categories) {
  const isDark = dom.html.getAttribute('data-theme') === 'dark';
  return categories.map(c => {
    const m = CATEGORY_META[c];
    return m ? (isDark ? m.darkColor : m.color) : '#94a3b8';
  });
}

function updateChart() {
  const totals     = getCategoryTotals();
  const categories = Object.keys(totals);
  const values     = categories.map(c => totals[c]);
  const colors     = getChartColors(categories);
  const hasData    = categories.length > 0;

  // Toggle chart visibility
  dom.chartWrapper.style.display = hasData ? 'block' : 'none';
  dom.chartLegend.style.display  = hasData ? 'flex'  : 'none';
  dom.chartEmpty.style.display   = hasData ? 'none'  : 'flex';

  if (!hasData) {
    if (pieChart) { pieChart.destroy(); pieChart = null; }
    return;
  }

  const isDark = dom.html.getAttribute('data-theme') === 'dark';
  const textColor = isDark ? '#e8eaf0' : '#1a1d23';

  const chartData = {
    labels:   categories,
    datasets: [{
      data:            values,
      backgroundColor: colors,
      borderColor:     isDark ? '#1a1d27' : '#ffffff',
      borderWidth:     3,
      hoverOffset:     8,
    }],
  };

  const chartOptions = {
    responsive:          true,
    maintainAspectRatio: true,
    animation:           { duration: 400 },
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          label: ctx => {
            const val   = ctx.parsed;
            const total = ctx.dataset.data.reduce((s, v) => s + v, 0);
            const pct   = ((val / total) * 100).toFixed(1);
            return ` ${formatCurrency(val)} (${pct}%)`;
          },
        },
        backgroundColor: isDark ? '#21253a' : '#1a1d23',
        titleColor:      '#ffffff',
        bodyColor:       '#ffffff',
        cornerRadius:    8,
        padding:         10,
      },
    },
  };

  if (pieChart) {
    // Update existing chart in-place
    pieChart.data    = chartData;
    pieChart.options = chartOptions;
    pieChart.update('active');
  } else {
    pieChart = new Chart(dom.pieCanvas, {
      type:    'doughnut',
      data:    chartData,
      options: chartOptions,
    });
  }

  // Custom HTML legend
  renderChartLegend(categories, colors, values);
}

function renderChartLegend(categories, colors, values) {
  const total = values.reduce((s, v) => s + v, 0);
  dom.chartLegend.innerHTML = categories.map((cat, i) => {
    const pct = total > 0 ? ((values[i] / total) * 100).toFixed(0) : 0;
    return `
      <div class="legend-item">
        <span class="legend-dot" style="background:${colors[i]}"></span>
        <span>${cat} (${pct}%)</span>
      </div>`;
  }).join('');
}

/* ═══════════════════════════════════════════
   9. CATEGORY SUMMARY BARS
═══════════════════════════════════════════ */

function renderSummary() {
  const totals     = getCategoryTotals();
  const categories = Object.keys(totals);

  if (categories.length === 0) {
    dom.summaryList.innerHTML = '<p class="summary-empty">No data yet.</p>';
    return;
  }

  const max    = Math.max(...Object.values(totals));
  const isDark = dom.html.getAttribute('data-theme') === 'dark';

  dom.summaryList.innerHTML = categories.map(cat => {
    const meta  = CATEGORY_META[cat] || {};
    const color = isDark ? (meta.darkColor || '#94a3b8') : (meta.color || '#94a3b8');
    const pct   = max > 0 ? ((totals[cat] / max) * 100).toFixed(1) : 0;
    const count = transactions.filter(t => t.category === cat).length;

    return `
      <div class="summary-item">
        <div class="summary-item-left">
          <span class="summary-dot" style="background:${color}"></span>
          <span>${meta.icon || ''} ${cat}</span>
          <span style="font-size:0.73rem;color:var(--color-text-muted)">(${count})</span>
        </div>
        <div class="summary-bar-track">
          <div class="summary-bar-fill" style="width:${pct}%;background:${color}"></div>
        </div>
        <div class="summary-right">${formatCurrency(totals[cat])}</div>
      </div>`;
  }).join('');
}

/* ═══════════════════════════════════════════
   10. MASTER RENDER
═══════════════════════════════════════════ */

function render() {
  updateBalanceUI();
  renderTransactionList();
  updateChart();
  renderSummary();
}

/* ═══════════════════════════════════════════
   11. UTILITY HELPERS
═══════════════════════════════════════════ */

function formatCurrency(amount) {
  return new Intl.NumberFormat('en-US', {
    style:                 'currency',
    currency:              'USD',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);
}

function formatDate(isoString) {
  const d = new Date(isoString);
  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day:   'numeric',
    hour:  '2-digit',
    minute:'2-digit',
  }).format(d);
}

function escapeHtml(str) {
  const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(str).replace(/[&<>"']/g, ch => map[ch]);
}

/* ═══════════════════════════════════════════
   12. EVENT LISTENERS
═══════════════════════════════════════════ */

function bindEvents() {
  // Theme toggle
  dom.themeToggle.addEventListener('click', toggleTheme);

  // Form submit
  dom.form.addEventListener('submit', handleFormSubmit);

  // Clear individual field errors on input
  dom.itemName.addEventListener('input', () => {
    dom.itemNameError.textContent = '';
    dom.itemName.classList.remove('error');
  });
  dom.amount.addEventListener('input', () => {
    dom.amountError.textContent = '';
    dom.amount.classList.remove('error');
  });
  dom.category.addEventListener('change', () => {
    dom.categoryError.textContent = '';
    dom.category.classList.remove('error');
  });

  // Sort change — just re-render the list (data unchanged)
  dom.sortSelect.addEventListener('change', () => {
    renderTransactionList();
  });

  // Delete (event delegation on the list container)
  dom.txList.addEventListener('click', e => {
    const btn = e.target.closest('.btn-delete');
    if (!btn) return;
    const id = btn.dataset.id;
    if (id) deleteTransaction(id);
  });
}

/* ═══════════════════════════════════════════
   13. BOOTSTRAP
═══════════════════════════════════════════ */

function init() {
  initTheme();
  loadTransactions();
  bindEvents();
  render();
}

// Wait for Chart.js to be available (it's loaded via CDN in <head>)
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

